];
const webhooks = {
  "Tech": "https://discord.com/api/webhooks/1565827809446993990/Rdxugmdo-4Cpd89i6TW6ey4ix-Ks_SSujQ294r2a5rLOmxO9oWW7MvOHJczeU6ZW3vYr",
  "ASMR": "https://discord.com/api/webhooks/1565829494273605823/bU1P8kEFTxupZGofLGGm5Aw7FWVDPwyhukwPEHtlELgi9HaX7cjs5_oEv4UszAmjY_be",
  "RPG": "https://discord.com/api/webhooks/1565830021690429521/wm7Q5m0zBBglDZor9GYjHjEtLa10TB098Icjua77hOXLjfT7OOamVYh02HiOhuW7hxou",
  "Cooking": "https://discord.com/api/webhooks/1565829867168207009/6us49MMobtcDp-UrRUxOtLnjOos3ygH6f7NmiCnsBQJ8sNt8hfEjVQZbRW7mxL9FbnBs"
};

const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};

const decode = (s) => s
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'").replace(/&amp;/g, '&');

const out = [];
for (const ch of channels) {
  let xml;
  try {
    xml = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://www.youtube.com/feeds/videos.xml?channel_id=${ch.channelId}`,
      returnFullResponse: false,
      timeout: 20000,
    });
  } catch (e) {
    console.log(`Feed failed for ${ch.name}: ${e.message}`);
    continue;
  }
  const videos = [...String(xml).matchAll(/<entry>([\s\S]*?)<\/entry>/g)].map((m) => {
    const e = m[1];
    const get = (re) => (e.match(re) || [])[1];
    return {
      id: get(/<yt:videoId>([^<]+)<\/yt:videoId>/),
      title: decode(get(/<title>([^<]*)<\/title>/) || ''),
      url: get(/<link rel="alternate" href="([^"]+)"/),
      published: get(/<published>([^<]+)<\/published>/),
    };
  }).filter((v) => v.id);

  const first = !state.seen[ch.channelId];
  const seen = new Set(state.seen[ch.channelId] || []);
  const fresh = videos.filter((v) => !seen.has(v.id));
  // First time we see a channel: record its videos, don't flood Discord.
  if (!first) {
    for (const v of fresh.sort((a, b) => a.published.localeCompare(b.published))) {
      out.push({ json: {
        category: ch.category,
        channel: ch.name,
        videoId: v.id,
        title: v.title,
        url: v.url,
        published: v.published,
        webhookUrl: webhooks[ch.category],
      } });
    }
  }
  state.seen[ch.channelId] = [...videos.map((v) => v.id), ...seen].slice(0, 100);
}
return out;

